CREATE TRIGGER play_events_subject AFTER INSERT ON play_events BEGIN UPDATE play_events SET raw_identity_key=NEW.identity_key,recording_id=CASE WHEN NEW.video_id IS NOT NULL THEN (SELECT recording_id FROM youtube_items WHERE video_id=NEW.video_id) ELSE COALESCE((SELECT recording_id FROM recording_redirects WHERE retired_id=COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))),COALESCE((SELECT id FROM recordings WHERE identity_key=NEW.identity_key),(SELECT MIN(recording_id) FROM recording_aliases WHERE alias=NEW.identity_key HAVING COUNT(DISTINCT recording_id)=1))) END WHERE rowid=NEW.rowid; UPDATE play_events SET identity_key=COALESCE((SELECT identity_key FROM recordings WHERE id=play_events.recording_id),identity_key) WHERE rowid=NEW.rowid; END
